import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import {
  FaBook,
  FaChartLine,
  FaTasks,
  FaCheckCircle,
  FaArrowUp,
  FaExclamationTriangle
} from "react-icons/fa";
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  PieChart,
  Pie,
  Cell,
  LineChart,
  Line
} from "recharts";
import AlertBox from "./AlertBox";
import AppShell from "./ui/AppShell";
import StatCard from "./ui/StatCard";
import Panel from "./ui/Panel";
import ChartCard from "./ui/ChartCard";
import "./theme.css";

function StudentDashboard() {
  const userId = localStorage.getItem("user_id");
  const userName = localStorage.getItem("user_name");

  const [courses, setCourses] = useState([]);
  const [progress, setProgress] = useState({});
  const [weekly, setWeekly] = useState({
    total_hours: 0,
    days_studied: 0,
    consistency: 0
  });
  const [logs, setLogs] = useState([]);
  const [alert, setAlert] = useState(null);

  const fetchAll = useCallback(async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );
      const enrolledIds = enrollRes.data.map((e) => e.course_id);
      const myCourses = allCourses.filter((c) => enrolledIds.includes(c.id));
      setCourses(myCourses);

      const progressRes = await axios.get(
        `http://127.0.0.1:8000/progress/${userId}`
      );
      const progressMap = {};
      (progressRes.data.progress || []).forEach((item) => {
        progressMap[item.course_id] = {
          completed_topics: item.completed_topics,
          total_topics: item.total_topics,
          status: item.status
        };
      });
      setProgress(progressMap);

      try {
        const weeklyRes = await axios.get(
          `http://127.0.0.1:8000/weekly-summary/${userId}`
        );
        setWeekly(weeklyRes.data);
      } catch {
        setWeekly({
          total_hours: 0,
          days_studied: 0,
          consistency: 0
        });
      }

      try {
        const logsRes = await axios.get(
          `http://127.0.0.1:8000/study-logs/${userId}`
        );
        setLogs(logsRes.data.logs || []);
      } catch {
        setLogs([]);
      }
    } catch (err) {
      console.error(err);
    }
  }, [userId]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const handleProgress = async (courseId, value) => {
    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/update-progress",
        {
          user_id: parseInt(userId),
          course_id: courseId,
          completed_topics: parseInt(value)
        }
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      fetchAll();
      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Failed to update progress",
        type: "error"
      });
    }
  };

  const completedCount = Object.values(progress).filter(
    (p) => p.status === "Completed"
  ).length;

  const averageProgress =
    courses.length > 0
      ? Math.round(
          courses.reduce((acc, course) => {
            const courseProgress = progress[course.id] || {
              completed_topics: 0,
              total_topics: 10
            };
            return (
              acc +
              (courseProgress.completed_topics / courseProgress.total_topics) *
                100
            );
          }, 0) / courses.length
        )
      : 0;

  const strongestCourse =
    courses.length > 0
      ? [...courses]
          .map((course) => {
            const p = progress[course.id] || {
              completed_topics: 0,
              total_topics: 10
            };
            return {
              title: course.title,
              percent: Math.round((p.completed_topics / p.total_topics) * 100)
            };
          })
          .sort((a, b) => b.percent - a.percent)[0]
      : null;

  const weakCourse =
    courses.length > 0
      ? [...courses]
          .map((course) => {
            const p = progress[course.id] || {
              completed_topics: 0,
              total_topics: 10
            };
            return {
              title: course.title,
              percent: Math.round((p.completed_topics / p.total_topics) * 100)
            };
          })
          .sort((a, b) => a.percent - b.percent)[0]
      : null;

  const courseChartData = courses.map((course) => {
    const p = progress[course.id] || {
      completed_topics: 0,
      total_topics: 10
    };
    return {
      name:
        course.title.length > 12
          ? course.title.slice(0, 12) + "..."
          : course.title,
      progress: Math.round((p.completed_topics / p.total_topics) * 100)
    };
  });

  const progressPieData = [
    { name: "Completed", value: completedCount },
    {
      name: "In Progress",
      value: Math.max(courses.length - completedCount, 0)
    }
  ];

  const studyLineData = (() => {
    const map = {};
    logs.forEach((log) => {
      const d = log.study_date;
      map[d] = (map[d] || 0) + Number(log.hours || 0);
    });

    return Object.keys(map)
      .sort()
      .slice(-7)
      .map((d) => ({
        date: d.slice(5),
        hours: map[d]
      }));
  })();

  return (
    <AppShell
      title="Student Dashboard"
      subtitle={`Welcome back, ${userName || "Student"}. Here’s your learning overview.`}
      action={
        <span className="badge badge-purple">
          <FaArrowUp />
          Active Learning
        </span>
      }
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-4" style={{ marginBottom: "18px" }}>
        <StatCard
          icon={<FaBook />}
          label="Enrolled Courses"
          value={courses.length}
          hint="Subjects you are currently learning"
        />
        <StatCard
          icon={<FaCheckCircle />}
          label="Completed Courses"
          value={completedCount}
          hint="Courses completed so far"
          accent="var(--success)"
        />
        <StatCard
          icon={<FaChartLine />}
          label="Average Progress"
          value={`${averageProgress}%`}
          hint="Across all enrolled courses"
          accent="var(--info)"
        />
        <StatCard
          icon={<FaTasks />}
          label="Strongest Course"
          value={strongestCourse ? strongestCourse.percent + "%" : "N/A"}
          hint={strongestCourse ? strongestCourse.title : "No course data yet"}
          accent="var(--warning)"
        />
      </div>

      <div className="page-grid-4" style={{ marginBottom: "18px" }}>
        <StatCard
          icon={<FaChartLine />}
          label="Weekly Hours"
          value={weekly.total_hours || 0}
          hint="Hours studied this week"
        />
        <StatCard
          icon={<FaTasks />}
          label="Days Studied"
          value={weekly.days_studied || 0}
          hint="Out of last 7 days"
        />
        <StatCard
          icon={<FaArrowUp />}
          label="Consistency"
          value={`${weekly.consistency || 0}%`}
          hint="Your weekly study consistency"
        />
        <StatCard
          icon={<FaCheckCircle />}
          label="Learning Status"
          value="On Track"
          hint="Keep your daily learning active"
          accent="var(--success)"
        />
      </div>

      <div className="page-grid-2" style={{ marginBottom: "18px" }}>
        <Panel title="Learning Summary">
          <div className="list-card">
            <h4 style={{ margin: 0 }}>Your focus this week</h4>
            <div className="muted" style={{ marginTop: "8px", lineHeight: 1.6 }}>
              Keep your progress above 70% in at least one subject. Try
              updating study progress regularly after every quiz, assignment, or
              study session.
            </div>
          </div>

          <div className="btn-row" style={{ marginTop: "14px" }}>
            <span className="badge badge-green">
              Consistent practice matters
            </span>
            <span className="badge badge-orange">Update progress daily</span>
          </div>
        </Panel>

        <Panel title="AI Recommendation">
          {weakCourse ? (
            <div className="list-card">
              <h4 style={{ marginTop: 0 }}>
                <FaExclamationTriangle style={{ marginRight: 8 }} />
                Focus Needed
              </h4>
              <div className="muted" style={{ lineHeight: 1.6 }}>
                You should focus more on <b>{weakCourse.title}</b>. Current
                progress is <b>{weakCourse.percent}%</b>. Try revising topics,
                attempting quizzes, and updating daily study logs.
              </div>
            </div>
          ) : (
            <p className="muted">No data yet.</p>
          )}
        </Panel>
      </div>

      <div className="page-grid-2" style={{ marginBottom: "18px" }}>
        <ChartCard
          title="Course Progress Overview"
          subtitle="Progress percentage by enrolled subject"
        >
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={courseChartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
              <XAxis dataKey="name" stroke="var(--)" />
              <YAxis stroke="var(--info)" />
              <Tooltip />
              <Bar
                dataKey="progress"
                fill="var(--primary)"
                radius={[8, 8, 0, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        </ChartCard>

        <ChartCard
          title="Completion Split"
          subtitle="Completed vs active courses"
        >
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={progressPieData}
                dataKey="value"
                nameKey="name"
                outerRadius={95}
                label
              >
                <Cell fill="#22c55e" />
                <Cell fill="#7c3aed" />
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      <div style={{ marginBottom: "18px" }}>
        <ChartCard
          title="Study Hours Trend"
          subtitle="Last 7 study log entries grouped by date"
        >
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={studyLineData}>
              <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
              <XAxis dataKey="date" stroke="var(--muted)" />
              <YAxis stroke="var(--muted)" />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="hours"
                stroke="var(--info)"
                strokeWidth={3}
              />
            </LineChart>
          </ResponsiveContainer>
        </ChartCard>
      </div>

      <Panel title="My Enrolled Courses">
        {courses.length === 0 ? (
          <p className="muted">No enrolled courses found.</p>
        ) : (
          <div className="page-grid-3">
            {courses.map((course) => {
              const courseProgress = progress[course.id] || {
                completed_topics: 0,
                total_topics: 10,
                status: "In Progress"
              };

              const percentage = Math.round(
                (courseProgress.completed_topics / courseProgress.total_topics) *
                  100
              );

              return (
                <div
                  key={course.id}
                  style={{
                    background: "var(--surface)",
                    border: "1px solid var(--border)",
                    borderRadius: "18px",
                    padding: "18px",
                    boxShadow: "var(--shadow-sm)"
                  }}
                >
                  <h4 style={{ marginTop: 0, marginBottom: "8px" }}>
                    {course.title}
                  </h4>

                  <div className="muted" style={{ lineHeight: 1.6 }}>
                    {course.description}
                  </div>

                  <div className="muted" style={{ marginTop: "8px" }}>
                    Subject Code: {course.subject_code}
                  </div>

                  <div className="muted" style={{ marginTop: "6px" }}>
                    Created By: {course.created_by || "Unknown"}
                  </div>

                  <div
                    style={{
                      height: "10px",
                      background: "var(--surface-2)",
                      borderRadius: "999px",
                      overflow: "hidden",
                      marginTop: "14px"
                    }}
                  >
                    <div
                      style={{
                        width: `${percentage}%`,
                        height: "100%",
                        background:
                          "linear-gradient(135deg, var(--primary), #a78bfa)"
                      }}
                    />
                  </div>

                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      gap: "12px",
                      alignItems: "center",
                      marginTop: "12px"
                    }}
                  >
                    <span className="muted">Progress: {percentage}%</span>

                    <span
                      className={
                        courseProgress.status === "Completed"
                          ? "badge badge-green"
                          : "badge badge-orange"
                      }
                    >
                      {courseProgress.status}
                    </span>
                  </div>

                  <input
                    className="input"
                    type="number"
                    min="0"
                    max={courseProgress.total_topics}
                    placeholder={`Completed topics (0-${courseProgress.total_topics})`}
                    id={`progress-${course.id}`}
                    style={{ marginTop: "14px" }}
                  />

                  <button
                    className="btn btn-primary"
                    style={{ width: "100%" }}
                    onClick={() => {
                      const value = document.getElementById(
                        `progress-${course.id}`
                      ).value;
                      handleProgress(course.id, value || 0);
                    }}
                  >
                    Update Progress
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </Panel>
    </AppShell>
  );
}

export default StudentDashboard;
